using System;
using System.Collections.Generic;
using System.Net;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using Moq;
using Volo.Abp.Cli.ProjectBuilding;
using Volo.Abp.Json;
using Xunit;

namespace Volo.Abp.Cli.Core.Tests.ProjectBuilding
{
    public class NpmPackageInfoProviderTests
    {
        [Fact]
        public async Task GetPackageListAsync_ReturnsDeserializedList()
        {
            // Arrange
            var expectedPackages = new List<NpmPackageInfo>
            {
                new NpmPackageInfo { Name = "TestPackage1" },
                new NpmPackageInfo { Name = "TestPackage2" }
            };

            var json = "[{\"Name\":\"TestPackage1\"},{\"Name\":\"TestPackage2\"}]";

            var httpResponse = new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent(json)
            };

            var mockHttpClient = new Mock<HttpClient>(MockBehavior.Strict);
            // HttpClient.GetAsync is not virtual, so we cannot mock it directly.
            // Instead, we will mock CliHttpClientFactory to return a HttpClient with a handler that returns the response.

            var handler = new FakeHttpMessageHandler(httpResponse);
            var client = new HttpClient(handler);

            var mockCliHttpClientFactory = new Mock<CliHttpClientFactory>();
            mockCliHttpClientFactory.Setup(f => f.CreateClient()).Returns(client);

            var mockJsonSerializer = new Mock<IJsonSerializer>();
            mockJsonSerializer.Setup(s => s.Deserialize<List<NpmPackageInfo>>(json)).Returns(expectedPackages);

            var mockCancellationTokenProvider = new Mock<ICancellationTokenProvider>();
            mockCancellationTokenProvider.SetupGet(c => c.Token).Returns(CancellationToken.None);

            var mockRemoteServiceExceptionHandler = new Mock<IRemoteServiceExceptionHandler>();
            mockRemoteServiceExceptionHandler
                .Setup(h => h.EnsureSuccessfulHttpResponseAsync(It.IsAny<HttpResponseMessage>()))
                .Returns(Task.CompletedTask);

            var provider = new NpmPackageInfoProvider(
                mockJsonSerializer.Object,
                mockCancellationTokenProvider.Object,
                mockRemoteServiceExceptionHandler.Object,
                mockCliHttpClientFactory.Object);

            // Act
            var result = await provider.GetPackageListAsync();

            // Assert
            Assert.NotNull(result);
            Assert.Equal(2, result.Count);
            Assert.Equal("TestPackage1", result[0].Name);
            Assert.Equal("TestPackage2", result[1].Name);
        }

        [Fact]
        public async Task GetAsync_ReturnsPackage_WhenFound()
        {
            // Arrange
            var packageName = "TestPackage1";
            var packages = new List<NpmPackageInfo>
            {
                new NpmPackageInfo { Name = packageName },
                new NpmPackageInfo { Name = "OtherPackage" }
            };

            var mockProvider = new Mock<NpmPackageInfoProvider>(
                MockBehavior.Strict,
                Mock.Of<IJsonSerializer>(),
                Mock.Of<ICancellationTokenProvider>(),
                Mock.Of<IRemoteServiceExceptionHandler>(),
                Mock.Of<CliHttpClientFactory>())
            {
                CallBase = true
            };

            mockProvider.Setup(p => p.GetPackageListAsync()).ReturnsAsync(packages);

            // Act
            var result = await mockProvider.Object.GetAsync(packageName);

            // Assert
            Assert.NotNull(result);
            Assert.Equal(packageName, result.Name);
        }

        [Fact]
        public async Task GetAsync_ThrowsException_WhenPackageNotFound()
        {
            // Arrange
            var packageName = "NonExistentPackage";
            var packages = new List<NpmPackageInfo>
            {
                new NpmPackageInfo { Name = "TestPackage1" },
                new NpmPackageInfo { Name = "OtherPackage" }
            };

            var mockProvider = new Mock<NpmPackageInfoProvider>(
                MockBehavior.Strict,
                Mock.Of<IJsonSerializer>(),
                Mock.Of<ICancellationTokenProvider>(),
                Mock.Of<IRemoteServiceExceptionHandler>(),
                Mock.Of<CliHttpClientFactory>())
            {
                CallBase = true
            };

            mockProvider.Setup(p => p.GetPackageListAsync()).ReturnsAsync(packages);

            // Act & Assert
            var ex = await Assert.ThrowsAsync<Exception>(() => mockProvider.Object.GetAsync(packageName));
            Assert.Equal("Package is not found or downloadable!", ex.Message);
        }

        private class FakeHttpMessageHandler : HttpMessageHandler
        {
            private readonly HttpResponseMessage _response;

            public FakeHttpMessageHandler(HttpResponseMessage response)
            {
                _response = response;
            }

            protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
            {
                return Task.FromResult(_response);
            }
        }
    }

    public class NpmPackageInfo
    {
        public string Name { get; set; }
    }
}
```

The CliHttpClientFactory creates HttpClient instances from an injected IHttpClientFactory and sets timeout and authentication. It does not expose a virtual or interface method for CreateClient, so I cannot mock it directly. But I can mock IHttpClientFactory to return a HttpClient with a custom HttpMessageHandler that returns a canned response.

I also see ICancellationTokenProvider is a dependency of CliHttpClientFactory, so I can mock it to provide CancellationToken.None.

I will write a test that mocks IHttpClientFactory to return a HttpClient with a fake handler, and mock ICancellationTokenProvider to provide CancellationToken.None. Then I will instantiate CliHttpClientFactory with these mocks and pass it to NpmPackageInfoProvider. This will allow me to test GetPackageListAsync and indirectly cover the HttpClient.GetAsync call.

